mapper.codeEditorJavascript:
const unidades = ['','um','dois','três','quatro','cinco','seis','sete','oito','nove',
  'dez','onze','doze','treze','quatorze','quinze','dezesseis','dezessete','dezoito','dezenove'];
const dezenas = ['','','vinte','trinta','quarenta','cinquenta','sessenta',
  'setenta','oitenta','noventa'];
const centenas = ['','cem','duzentos','trezentos','quatrocentos','quinhentos',
  'seiscentos','setecentos','oitocentos','novecentos'];

function grupo(n) {
  if (n === 0) return '';
  if (n === 100) return 'cem';
  let r = '';
  const c = Math.floor(n / 100);
  const resto = n % 100;
  if (c > 0) r += centenas[c];
  if (c > 0 && resto > 0) r += ' e ';
  if (resto > 0 && resto < 20) r += unidades[resto];
  else if (resto >= 20) {
    r += dezenas[Math.floor(resto / 10)];
    if (resto % 10 > 0) r += ' e ' + unidades[resto % 10];
  }
  return r;
}

function cardinal(n) {
  if (n === 0) return 'zero';
  if (n < 0) return 'menos ' + cardinal(-n);
  const bilhoes = Math.floor(n / 1e9);
  const milhoes = Math.floor((n % 1e9) / 1e6);
  const milhares = Math.floor((n % 1e6) / 1e3);
  const resto = n % 1e3;
  let partes = [];
  if (bilhoes > 0) partes.push(grupo(bilhoes) + (bilhoes === 1 ? ' bilhão' : ' bilhões'));
  if (milhoes > 0) partes.push(grupo(milhoes) + (milhoes === 1 ? ' milhão' : ' milhões'));
  // CORREÇÃO: "mil", não "um mil"
  if (milhares > 0) partes.push((milhares === 1 ? '' : grupo(milhares) + ' ') + 'mil');
  if (resto > 0) partes.push(grupo(resto));
  return partes.join(' e ');
}

// CORREÇÃO: detecta automaticamente se é formato BR (1.500,75) ou US (1,500.75)
// pela posição do último "," ou "." na string
function normalizarNumero(valor) {
  if (typeof valor === 'number') return valor;

  const str = String(valor).trim();
  const ultimaVirgula = str.lastIndexOf(',');
  const ultimoPonto = str.lastIndexOf('.');

  let normalizado;
  if (ultimaVirgula > ultimoPonto) {
    normalizado = str.replace(/\./g, '').replace(',', '.');
  } else if (ultimoPonto > ultimaVirgula) {
    normalizado = str.replace(/,/g, '');
  } else {
    normalizado = str;
  }
  return parseFloat(normalizado);
}

function monetario(valor) {
  const num = normalizarNumero(valor);
  if (isNaN(num)) return 'valor inválido';

  const negativo = num < 0;
  const absoluto = Math.abs(num);

  const reais = Math.floor(absoluto);
  const centavos = Math.round((absoluto - reais) * 100);

  let partes = [];

  if (reais > 0) {
    const labelReal = reais === 1 ? 'real' : 'reais';
    partes.push(cardinal(reais) + ' ' + labelReal);
  }

  if (centavos > 0) {
    const labelCentavo = centavos === 1 ? 'centavo' : 'centavos';
    partes.push(cardinal(centavos) + ' ' + labelCentavo);
  }

  if (partes.length === 0) return 'zero reais';

  let resultado = partes.join(' e ');
  if (negativo) resultado = 'menos ' + resultado;

  return resultado;
}

// Ponto de entrada: recebe a variável "number" mapeada no Make
return {
  extenso1: monetario(input.number1),
  extenso2: monetario(input.number2)
};

